/** Prepared Google Privacy & messaging integration. No third-party request while disabled. */
export const CONSENT_CMP_ENABLED = false;
/** Paste the script URL generated by the published Google CMP message, never an invented tag. */
export const GOOGLE_CMP_MESSAGE_SRC: string | null = null;
export const CMP_REGIONS = ["EEA", "United Kingdom", "Switzerland"] as const;

export function certifiedCmpSource(enabled: boolean = CONSENT_CMP_ENABLED, source: string | null = GOOGLE_CMP_MESSAGE_SRC): string | null {
  if (!enabled) return null;
  if (!source) throw new Error("Publish and configure the Google CMP message before activation");
  const url = new URL(source);
  if (url.protocol !== "https:" || url.hostname !== "fundingchoicesmessages.google.com" || !url.pathname.startsWith("/i/") || url.username || url.password || url.hash) throw new Error("Use the official Google Privacy & messaging script URL");
  return url.href;
}
